  1→//! Dependency graph for step execution ordering.
  2→
  3→use std::collections::{HashMap, HashSet, VecDeque};
  4→
  5→use crate::error::{BivvyError, Result};
  6→
  7→/// How to handle skipping a step that has dependents.
  8→#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
  9→pub enum SkipBehavior {
 10→    /// Skip the step and all its dependents.
 11→    #[default]
 12→    SkipWithDependents,
 13→    /// Don't skip - run the step anyway.
 14→    RunAnyway,
 15→    /// Skip only this step, attempt to run dependents.
 16→    SkipOnly,
 17→}
 18→
 19→/// Represents the dependency relationships between steps.
 20→#[derive(Debug, Clone)]
 21→pub struct DependencyGraph {
 22→    /// Map of step name to its direct dependencies.
 23→    dependencies: HashMap<String, HashSet<String>>,
 24→    /// Map of step name to steps that depend on it.
 25→    dependents: HashMap<String, HashSet<String>>,
 26→    /// All step names in the graph.
 27→    steps: HashSet<String>,
 28→}
 29→
 30→impl DependencyGraph {
 31→    /// Create a new dependency graph builder.
 32→    pub fn builder() -> DependencyGraphBuilder {
 33→        DependencyGraphBuilder::new()
 34→    }
 35→
 36→    /// Get the direct dependencies of a step.
 37→    pub fn dependencies_of(&self, step: &str) -> Option<&HashSet<String>> {
 38→        self.dependencies.get(step)
 39→    }
 40→
 41→    /// Get steps that depend on the given step.
 42→    pub fn dependents_of(&self, step: &str) -> Option<&HashSet<String>> {
 43→        self.dependents.get(step)
 44→    }
 45→
 46→    /// Check if a step exists in the graph.
 47→    pub fn contains(&self, step: &str) -> bool {
 48→        self.steps.contains(step)
 49→    }
 50→
 51→    /// Get all step names.
 52→    pub fn steps(&self) -> &HashSet<String> {
 53→        &self.steps
 54→    }
 55→
 56→    /// Get the number of steps in the graph.
 57→    pub fn len(&self) -> usize {
 58→        self.steps.len()
 59→    }
 60→
 61→    /// Check if the graph is empty.
 62→    pub fn is_empty(&self) -> bool {
 63→        self.steps.is_empty()
 64→    }
 65→
 66→    /// Returns steps in topological order (dependencies before dependents).
 67→    ///
 68→    /// Returns an error if a cycle is detected.
 69→    pub fn topological_order(&self) -> Result<Vec<String>> {
 70→        // Count incoming edges for each node
 71→        let mut in_degree: HashMap<String, usize> = HashMap::new();
 72→        for step in &self.steps {
 73→            in_degree.insert(
 74→                step.clone(),
 75→                self.dependencies.get(step).map_or(0, |d| d.len()),
 76→            );
 77→        }
 78→
 79→        // Start with nodes that have no dependencies
 80→        let mut queue: VecDeque<String> = in_degree
 81→            .iter()
 82→            .filter(|(_, &degree)| degree == 0)
 83→            .map(|(step, _)| step.clone())
 84→            .collect();
 85→
 86→        let mut result = Vec::with_capacity(self.steps.len());
 87→
 88→        while let Some(step) = queue.pop_front() {
 89→            result.push(step.clone());
 90→
 91→            // Reduce in-degree for all dependents
 92→            if let Some(dependents) = self.dependents.get(&step) {
 93→                for dependent in dependents {
 94→                    if let Some(degree) = in_degree.get_mut(dependent) {
 95→                        *degree -= 1;
 96→                        if *degree == 0 {
 97→                            queue.push_back(dependent.clone());
 98→                        }
 99→                    }
100→                }

  1→//! Output masking for secret values.
  2→//!
  3→//! This module provides functionality for masking sensitive values in output streams.
  4→
  5→use std::collections::HashMap;
  6→use std::io::{self, Write};
  7→
  8→/// Masks secret values in output streams.
  9→///
 10→/// # Example
 11→///
 12→/// ```
 13→/// use bivvy::secrets::OutputMasker;
 14→///
 15→/// let mut masker = OutputMasker::new();
 16→/// masker.add_secret("super-secret-value");
 17→///
 18→/// let output = masker.mask("The key is super-secret-value here");
 19→/// assert_eq!(output, "The key is [REDACTED] here");
 20→/// assert!(!output.contains("super-secret-value"));
 21→/// ```
 22→pub struct OutputMasker {
 23→    /// Map of secret values to their masked representation.
 24→    secrets: HashMap<String, String>,
 25→    /// The mask string to use.
 26→    mask: String,
 27→}
 28→
 29→impl OutputMasker {
 30→    /// Create a new masker with default mask string.
 31→    pub fn new() -> Self {
 32→        Self {
 33→            secrets: HashMap::new(),
 34→            mask: "[REDACTED]".to_string(),
 35→        }
 36→    }
 37→
 38→    /// Create a masker with a custom mask string.
 39→    ///
 40→    /// # Example
 41→    ///
 42→    /// ```
 43→    /// use bivvy::secrets::OutputMasker;
 44→    ///
 45→    /// let mut masker = OutputMasker::with_mask("***");
 46→    /// masker.add_secret("password123");
 47→    ///
 48→    /// let output = masker.mask("password: password123");
 49→    /// assert_eq!(output, "password: ***");
 50→    /// ```
 51→    pub fn with_mask(mask: impl Into<String>) -> Self {
 52→        Self {
 53→            secrets: HashMap::new(),
 54→            mask: mask.into(),
 55→        }
 56→    }
 57→
 58→    /// Register a secret value to be masked.
 59→    ///
 60→    /// Empty strings are ignored.
 61→    pub fn add_secret(&mut self, value: impl Into<String>) {
 62→        let value = value.into();
 63→        if !value.is_empty() {
 64→            self.secrets.insert(value, self.mask.clone());
 65→        }
 66→    }
 67→
 68→    /// Register multiple secret values.
 69→    pub fn add_secrets(&mut self, values: impl IntoIterator<Item = impl Into<String>>) {
 70→        for value in values {
 71→            self.add_secret(value);
 72→        }
 73→    }
 74→
 75→    /// Mask any secret values in the given string.
 76→    pub fn mask(&self, input: &str) -> String {
 77→        let mut result = input.to_string();
 78→        for (secret, mask) in &self.secrets {
 79→            result = result.replace(secret, mask);
 80→        }
 81→        result
 82→    }
 83→
 84→    /// Get the number of registered secrets.
 85→    pub fn secret_count(&self) -> usize {
 86→        self.secrets.len()
 87→    }
 88→
 89→    /// Create a writer that masks output.
 90→    ///
 91→    /// # Example
 92→    ///
 93→    /// ```
 94→    /// use bivvy::secrets::OutputMasker;
 95→    /// use std::io::Write;
 96→    ///
 97→    /// let mut masker = OutputMasker::new();
 98→    /// masker.add_secret("secret-value");
 99→    ///
100→    /// let mut output = Vec::new();
101→    /// {
102→    ///     let mut writer = masker.writer(&mut output);
103→    ///     writeln!(writer, "The value is secret-value").unwrap();
104→    ///     writer.flush().unwrap();
105→    /// }
106→    ///
107→    /// let result = String::from_utf8(output).unwrap();
108→    /// assert!(result.contains("[REDACTED]"));
109→    /// assert!(!result.contains("secret-value"));
110→    /// ```
111→    pub fn writer<W: Write>(&self, inner: W) -> MaskingWriter<'_, W> {
112→        MaskingWriter {
113→            inner,
114→            masker: self,
115→            buffer: String::new(),
116→        }
117→    }
118→}
119→
120→impl Default for OutputMasker {
121→    fn default() -> Self {
122→        Self::new()
123→    }
124→}
125→
126→/// A writer that masks secret values.
127→///
128→/// This wraps another writer and replaces any secret values with their
129→/// masked representation before writing.
130→pub struct MaskingWriter<'a, W: Write> {
131→    inner: W,
132→    masker: &'a OutputMasker,
133→    buffer: String,
134→}
135→
136→impl<W: Write> Write for MaskingWriter<'_, W> {
137→    fn write(&mut self, buf: &[u8]) -> io::Result<usize> {
138→        let input = String::from_utf8_lossy(buf);
139→        self.buffer.push_str(&input);
140→
141→        // Process complete lines
142→        while let Some(newline_pos) = self.buffer.find('\n') {
143→            let line = self.buffer[..=newline_pos].to_string();
144→            self.buffer = self.buffer[newline_pos + 1..].to_string();
145→            let masked = self.masker.mask(&line);
146→            self.inner.write_all(masked.as_bytes())?;
147→        }
148→
149→        Ok(buf.len())
150→    }
151→
152→    fn flush(&mut self) -> io::Result<()> {
153→        if !self.buffer.is_empty() {
154→            let masked = self.masker.mask(&self.buffer);
155→            self.inner.write_all(masked.as_bytes())?;
156→            self.buffer.clear();
157→        }
158→        self.inner.flush()
159→    }
160→}
