    #[test]
    fn mock_ui_multiselect_returns_strings_from_default() {
        let mut ui = MockUI::new();

        let prompt = Prompt {
            key: "steps".to_string(),
            question: "Select steps".to_string(),
            prompt_type: PromptType::MultiSelect {
                options: vec![PromptOption {
                    label: "Bundler".to_string(),
