            steps_run: 1,
            steps_skipped: 0,
            success: true,
            failed_steps: vec![],
        };
        ui.show_run_summary(&summary);

        assert!(!ui.run_headers().is_empty());
        assert!(!ui.error_blocks().is_empty());
        assert!(!ui.summaries().is_empty());

        ui.clear();

        assert!(ui.run_headers().is_empty());
        assert!(ui.error_blocks().is_empty());
