    #[test]
    fn save_report_same_second_same_step_overwrites() {
        // This test demonstrates the race condition: two reports with the same
        // step name saved in the same second produce the same filename, so the
        // second write silently overwrites the first.
        let temp = tempfile::TempDir::new().unwrap();

        let report_a = FailureReport {
            step_name: "deploy".to_string(),
            command_scrubbed: "first command".to_string(),
            exit_code: Some(1),
            error_scrubbed: "first error".to_string(),
            recovery_action: "retry".to_string(),
            bivvy_version: "1.0.0".to_string(),
            platform: "test-platform".to_string(),
        };

        let report_b = FailureReport {
            step_name: "deploy".to_string(),
            command_scrubbed: "second command".to_string(),
            exit_code: Some(2),
            error_scrubbed: "second error".to_string(),
            recovery_action: "fix".to_string(),
            bivvy_version: "1.0.0".to_string(),
            platform: "test-platform".to_string(),
        };

        let path_a = save_report_to(&report_a, temp.path()).unwrap();
        let path_b = save_report_to(&report_b, temp.path()).unwrap();

        // Same second + same step name = same filename = overwrite
        assert_eq!(path_a, path_b, "same-second saves produce identical paths");

        // Only one file exists — the first report was silently dropped
        let files: Vec<_> = std::fs::read_dir(temp.path())
            .unwrap()
            .filter_map(|e| e.ok())
            .collect();
        assert_eq!(
            files.len(),
            1,
            "expected exactly 1 file (second overwrote first), got {}",
            files.len()
        );

        // The surviving file contains the second report's data
        let content = std::fs::read_to_string(&path_b).unwrap();
        assert!(
            content.contains("second command"),
            "surviving report should be the second one"
        );
    }

